package org.sleepwell.app;
import android.content.Context;import android.net.Uri;import android.os.*;import java.io.*;import java.lang.ref.WeakReference;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;
/** Retains an exact reviewed snapshot; no network, services or telemetry. */
final class ResearchExportJob {
 enum Phase{PREPARING,READY,CHOOSING,WRITING,DONE,ERROR}
 static final class State {final Phase phase;final int days;final ResearchSignals.Snapshot snapshot;final String message;State(Phase phase,int days,ResearchSignals.Snapshot snapshot,String message){this.phase=phase;this.days=days;this.snapshot=snapshot;this.message=message;}boolean busy(){return phase==Phase.PREPARING||phase==Phase.WRITING||phase==Phase.CHOOSING;}}
 interface Observer {void changed(State state);}
 private static final Executor CANCEL=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->{Thread thread=new Thread(r,"signal-export-cancel");thread.setDaemon(true);return thread;},new ThreadPoolExecutor.DiscardPolicy());
 final Context app;final Records.Factory records;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();final AtomicReference<CancellationSignal> signal=new AtomicReference<>();final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();private WeakReference<Observer> observer=new WeakReference<>(null);private volatile boolean closed;private volatile State state;private ResearchSignals.Snapshot owned;int choiceRequest=500+java.util.concurrent.ThreadLocalRandom.current().nextInt(20000);
 ResearchExportJob(Context context,Records.Factory factory,int days,boolean restarted){app=context.getApplicationContext();records=factory;prepare(days,restarted?"Previous operation was interrupted. Review this new snapshot before saving; an earlier destination may contain a partial file.":"");}
 State state(){return state;}void observe(Observer value){observer=new WeakReference<>(value);value.changed(state);}void detach(Observer value){if(observer.get()==value)observer.clear();}private void publish(State value){if(closed)return;state=value;Observer target=observer.get();if(target!=null)target.changed(value);}
 void prepare(int days){if(closed||state!=null&&state.busy())return;prepare(days,"");}
 private void prepare(int days,String message){if(!java.util.Set.of(7,30,90).contains(days))days=7;int window=days;publish(new State(Phase.PREPARING,days,null,message));long admission=BackupRuntime.generation();worker.execute(()->{try{if(owned!=null){owned.close();owned=null;}try(Store store=records.open(app)){owned=ResearchSignals.prepare(app,store,window,System.currentTimeMillis(),()->!closed,admission);}ResearchSignals.Snapshot snapshot=owned;String status=snapshot.nights==0?"No eligible measured nights in this window. Rejected and unknown records are counted; no missing signal was filled.":message;main.post(()->publish(new State(Phase.READY,window,snapshot,status)));}catch(Exception error){String failure=notice(error);main.post(()->publish(new State(Phase.ERROR,window,null,"Signal snapshot could not be prepared: "+failure)));}});}
 private static String notice(Exception error){String message=error.getMessage();if(error instanceof FileNotFoundException||message==null||message.isBlank()||message.length()>320)return "Storage or document access failed. Try again.";return message;}
 boolean choose(){State before=state;if(closed||before==null||before.busy()||before.snapshot==null||before.snapshot.nights==0)return false;choiceRequest=choiceRequest>=30000?500:choiceRequest+1;publish(new State(Phase.CHOOSING,before.days,before.snapshot,"Choose where to save the reviewed signal ZIP."));return true;}
 void cancelChoice(){if(state.phase==Phase.CHOOSING)publish(new State(Phase.READY,state.days,state.snapshot,"Save location cancelled. Nothing was written."));}
 void write(Uri uri){if(closed||state.phase!=Phase.CHOOSING||state.snapshot==null)return;if(uri==null||!"content".equals(uri.getScheme())){publish(new State(Phase.ERROR,state.days,state.snapshot,"Choose a destination through Android Files."));return;}ResearchSignals.Snapshot snapshot=state.snapshot;int days=state.days;publish(new State(Phase.WRITING,days,snapshot,"Writing the exact reviewed snapshot…"));worker.execute(()->{try{CancellationSignal cancellation=new CancellationSignal();signal.set(cancellation);try{NightAudioArchive.active(()->!closed);ParcelFileDescriptor file=app.getContentResolver().openFileDescriptor(uri,"wt",cancellation);if(file==null)throw new IOException("Destination unavailable.");descriptor.set(file);try(OutputStream output=new ParcelFileDescriptor.AutoCloseOutputStream(file)){snapshot.write(output,()->!closed);}finally{descriptor.compareAndSet(file,null);}}finally{signal.compareAndSet(cancellation,null);}main.post(()->publish(new State(Phase.DONE,days,snapshot,"Signal ZIP saved and closed. No automatic upload or research submission occurred.")));}catch(Exception error){String failure=notice(error);main.post(()->publish(new State(Phase.ERROR,days,snapshot,"Export failed; the destination may contain a partial file. "+failure)));}});}
 void close(){if(closed)return;closed=true;observer.clear();CancellationSignal pending=signal.get();ParcelFileDescriptor file=descriptor.get();CANCEL.execute(()->{if(pending!=null)pending.cancel();if(file!=null)try{file.close();}catch(IOException ignored){}});worker.execute(()->{if(owned!=null){try{owned.close();}catch(IOException ignored){}owned=null;}});worker.shutdown();}
}
